-- Beyond Branding Pitch Playbook: database setup for Supabase
-- Paste this whole file into Supabase > SQL Editor > New query, then press Run.

-- 1. The leads table. Each lead is one row; its details live in the "data" column as JSON,
--    so you can add new fields later without changing the table.
create table if not exists public.leads (
  id          text primary key,
  data        jsonb not null,
  updated_at  timestamptz not null default now()
);

-- 2. Security: only people signed in to your Supabase project can read or change leads.
--    Turn off public sign-ups (Authentication > Sign In / Providers) and invite partners by email,
--    so only people you invite can sign in.
alter table public.leads enable row level security;

drop policy if exists "Team can read leads"   on public.leads;
drop policy if exists "Team can add leads"    on public.leads;
drop policy if exists "Team can update leads" on public.leads;

create policy "Team can read leads"   on public.leads for select to authenticated using (true);
create policy "Team can add leads"    on public.leads for insert to authenticated with check (true);
create policy "Team can update leads" on public.leads for update to authenticated using (true) with check (true);
-- No delete policy on purpose: delete rows from the Supabase Table Editor, not from the app.

-- 3. Live updates: when a partner claims a lead, everyone else's screen updates.
do $$ begin
  alter publication supabase_realtime add table public.leads;
exception when duplicate_object then null; end $$;

-- 4. The first 35 leads, researched 26 Oct 2026.
on conflict (id) do nothing;
